const automationStatus={scheduled:'Agendada',processing:'Processada',simulated:'Envio simulado',blocked:'Bloqueada',failed:'Falha',cancelled:'Cancelada'};
function automationTiming(r){return r.delayMinutes?`Após ${r.delayMinutes} minuto(s)`:'Imediato'}
function automationConditions(r){return [r.origin||'Todas as origens',r.direction||'Inbound e Outbound',r.event==='stage'?(r.stage===''?'Todas as etapas':D.STAGES[r.stage]):''].filter(Boolean).join(' · ')}
const mailingStatus={draft:'Aguardando revisão',active:'Ativo',paused:'Pausado',completed:'Concluído',cancelled:'Cancelado'};
