function automationReview(id){
 const r=state.automations.find(r=>r.id===id);if(!r)throw Error('Automação não encontrada.');
 const previewContact={name:'Maria Exemplo',origin:r.origin||'Site',stage:r.stage===''?0:r.stage},payment={id:'example',contactId:'example',amount:100,receipt:'LUZ-EXEMPLO'};
 const preview=D.renderAutomationMessage({payments:[payment]},r,{stage:previewContact.stage,paymentId:'example'},{...previewContact,id:'example'});
 modal('Revisar automação',`<h3>${esc(r.name)}</h3><p class="notice green">${esc(D.AUTO_EVENTS[r.event])}<br>${esc(automationConditions(r))}<br>${automationTiming(r)}</p><small>Exemplo de mensagem · dados fictícios</small><h3 class="automation-subject">${esc(preview.subject)}</h3><div class="campaign-preview">${esc(preview.body)}</div><p class="automation-meta">A ativação vale para novos eventos. Cadastros e contribuições anteriores não disparam mensagens retroativas.</p>`,button('Voltar','close')+button('Ativar automação','automation-activate',id,'','check'));
 $f('[data-action=automation-activate]').onclick=e=>{e.stopPropagation();try{activeUser();D.setAutomationActive(state,user,id,true);save();closeModal();render();toast('Automação ativada para novos eventos.')}catch(err){toast(err.message,'error')}};
}
function automationRunDetail(id){
 const r=state.automationRuns.find(r=>r.id===id);if(!r)throw Error('Execução não encontrada.');
 modal('Execução de automação',`<h3>${esc(r.rule.name)}</h3><p class="automation-subject">${badge(automationStatus[r.status],r.status==='failed'||r.status==='blocked'?'red':'')}</p><dl class="details"><div><dt>Contato</dt><dd>${esc(r.contactName)}</dd></div><div><dt>Destinatário</dt><dd>${esc(r.recipient||'Sem e-mail')}</dd></div><div><dt>Evento</dt><dd>${esc(D.AUTO_EVENTS[r.event.type])} · ${time(r.event.at)}</dd></div><div><dt>Previsão</dt><dd>${time(r.dueAt)}</dd></div><div><dt>Configuração</dt><dd>${esc(r.rule.updatedByName)} · versão ${r.rule.version}</dd></div><div><dt>Execução</dt><dd>Sistema · ${r.attempts.length} tentativa(s)</dd></div></dl><p class="notice">${esc(r.detail)}</p><h3>${esc(r.subject||r.rule.subject)}</h3><div class="campaign-preview">${esc(r.body||r.rule.body)}</div><h3 class="automation-subject">Histórico</h3><div class="timeline">${r.transitions.map(t=>`<article class="event"><h3>${esc(automationStatus[t.status])}</h3><p>${esc(t.detail)}</p><small>${time(t.at)} · Sistema</small></article>`).join('')}</div>`,button('Fechar','close')+(state.contacts.some(c=>c.id===r.contactId)?button('Abrir ficha','profile',r.contactId,'secondary'):'')+(r.status==='scheduled'?button('Cancelar envio','automation-cancel',id,'secondary')+button('Simular agora','automation-now',id,'','mail'):r.status==='failed'?button('Tentar novamente','automation-retry',id,'','mail'):''),true);
}
function bindOriginDirection(){
 const origin=$f('[name=origin]'),direction=$f('[name=funnel]');
 const update=()=>{
  const inboundOnly=['Site','Instagram'].includes(origin.value),value=inboundOnly?'Inbound':direction.value;
  direction.innerHTML=['Inbound','Outbound'].map(v=>`<option value="${v}">${v}</option>`).join('');
  direction.value=value;direction.disabled=inboundOnly;
 };
 origin.onchange=update;update();
}
function moveLossForm(id){
 const c=state.contacts.find(c=>c.id===id);if(!D.outsideCadence(c))throw Error('Contato não está no funil de perdas.');
 formModal('Mover etapa de perdas',`<p class="notice green">${esc(c.name)} · ${esc(c.cadenceExit.reason)}</p>${selectField('Etapa de perdas','lossStage',D.LOSS_STAGES.map((name,i)=>[i,name]),D.lossStage(c))}${field('Data da retomada *','followUpDate',c.cadenceExit.followUpDate||D.today(),'date',`min="${D.today()}"`)}<div class="field"><label for="f-note">Observação da movimentação</label><textarea id="f-note" name="note" maxlength="2000"></textarea></div>`,d=>{D.moveLoss(state,user,id,Number(d.lossStage),d.note,d.followUpDate);save();closeModal();render();profile(id);toast('Etapa de perdas atualizada.')},'Salvar etapa');
 const update=()=>{const input=$f('[name=followUpDate]'),scheduled=$f('[name=lossStage]').value==='2';input.closest('.field').hidden=!scheduled;input.required=scheduled;input.disabled=!scheduled};
 $f('[name=lossStage]').onchange=update;update();
}
function resumeCadenceForm(id){
 const c=state.contacts.find(c=>c.id===id);if(!D.outsideCadence(c))throw Error('Contato não está fora da cadência.');
 formModal('Retomar cadência',`<p class="notice green">${esc(c.name)} · ${esc(c.cadenceExit.reason)}. A retomada preserva o histórico e o status financeiro.</p>${selectField('Etapa de retorno','stage',D.STAGES.map((name,i)=>[i,name]),c.cadenceExit.stage)}<div class="field"><label for="f-reason">Motivo da retomada *</label><textarea id="f-reason" name="reason" required maxlength="2000"></textarea></div>`,d=>{D.resumeCadence(state,user,id,Number(d.stage),d.reason);save();closeModal();render();profile(id);toast('Relacionamento retornou à cadência.')},'Retomar cadência');
}
function visibleContacts(){return filterContacts().filter(c=>page==='donors'?c.plan:tab==='leads'?!c.plan:tab==='donors'?c.plan:true)}
function emailEligible(c){return Boolean(c?.email&&D.emailValid(c.email)&&!c.optOut)}
function cleanContactSelection(){selectedContacts=new Set([...selectedContacts].filter(id=>emailEligible(state.contacts.find(c=>c.id===id))))}
function selectionToolbar(cs){
  cleanContactSelection();
  const eligible=cs.filter(emailEligible),allSelected=eligible.length>0&&eligible.every(c=>selectedContacts.has(c.id));
  return `<div class="contact-selection-bar"><label class="select-filtered"><input type="checkbox" data-action="select-filtered" ${allSelected?'checked':''} ${eligible.length?'':'disabled'} aria-label="Selecionar todos os contatos elegíveis deste filtro"> Selecionar todos do filtro <small>(${eligible.length})</small></label><span class="selection-count" aria-live="polite">${selectedContacts.size} ${selectedContacts.size===1?'selecionado':'selecionados'}</span><div class="selection-actions">${selectedContacts.size?button('Limpar seleção','clear-selection','','quiet small'):''}${button('Redigir e-mail','bulk-email','','small','mail')}</div></div>`;
}
function contacts(){
  const isDonors=page==='donors',cs=visibleContacts(),pages=Math.max(1,Math.ceil(cs.length/10));contactPage=Math.min(contactPage,pages);
  return heading(isDonors?'Quem caminha com a nossa causa':'Cada contato, uma nova possibilidade',isDonors?'Acompanhe contribuições e cuide de quem sustenta nossas obras sociais.':'Pessoas e organizações que fazem parte da nossa rede de esperança.',button('Exportar','export-contacts','','secondary','download')+button('Novo contato','contact','','','plus'))+(!isDonors?`<div class="tabs">${[['all','Todos os contatos'],['leads','Potenciais doadores'],['donors','Doadores']].map(([v,l])=>`<button class="tab ${tab===v?'active':''}" data-action="contact-tab" data-id="${v}">${l}</button>`).join('')}</div>`:'')+filtersHTML(select('status',isDonors?[...D.DONOR_STATUSES,'Sócio Inscrito']:['Potencial doador',...D.DONOR_STATUSES,'Sócio Inscrito'],filters.status,'Todos os status'))+`<section class="panel contacts-panel">${selectionToolbar(cs)}${cs.length?`<div class="table-wrap"><table><thead><tr><th class="checkbox-cell"><span class="sr-only">Selecionar destinatário</span></th><th>Relacionamento</th><th>Origem</th><th>${isDonors?'Compromisso / recebido':'Etapa / compromisso'}</th><th>Status</th><th>Responsável</th><th></th></tr></thead><tbody>${cs.slice((contactPage-1)*10,contactPage*10).map(c=>`<tr class="${selectedContacts.has(c.id)?'selected-row':''}"><td class="checkbox-cell"><input type="checkbox" data-action="select-contact" data-id="${c.id}" aria-label="Selecionar ${esc(c.name)} para enviar e-mail" ${selectedContacts.has(c.id)?'checked':''} ${emailEligible(c)?'':`disabled title="${c.optOut?'Contato descadastrado de e-mails':'Sem e-mail válido'}"`}></td><td>${contactCell(c)}</td><td>${esc(c.origin)}<small style="display:block">${c.funnel}</small></td><td>${c.plan?'Compromisso: '+money(c.plan.amount)+'<small style="display:block">'+c.plan.mode+' · Recebido: '+money(total(state.payments.filter(p=>p.contactId===c.id)))+'</small>':esc(D.STAGES[c.stage])}</td><td>${statusBadge(c)} ${c.optOut?badge('Descadastrado','gray'):''}</td><td>${esc(state.users.find(u=>u.id===c.owner)?.name||'—')}</td><td><button class="icon-button" data-action="profile" data-id="${c.id}" aria-label="Abrir ficha de ${esc(c.name)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div class="flex between" style="padding:16px 22px;border-top:1px solid var(--line)"><small>${cs.length} relacionamentos · Página ${contactPage} de ${pages}</small><div class="flex"><button class="btn secondary small" data-action="prev" ${contactPage<=1?'disabled':''}>Anterior</button><button class="btn secondary small" data-action="next" ${contactPage>=pages?'disabled':''}>Próxima</button></div></div>`:empty('Nenhum relacionamento encontrado para estes filtros.')}</section>`;
}
function lists(){const ls=state.lists.filter(l=>!filters.q||(l.name+' '+l.category).toLowerCase().includes(filters.q.toLowerCase()));return heading('Cultive novas conexões','Organize a prospecção ativa e acompanhe as respostas da comunidade.',button('Nova campanha','campaign','','secondary','mail')+button('Nova lista','list','','','plus'))+`<div class="filters"><div class="search">${icon('search')}<input id="search" type="search" aria-label="Buscar listas" placeholder="Buscar uma lista…" value="${esc(filters.q)}"></div><span class="toolbar-end muted" style="font-size:11px">${state.lists.length} listas · ${state.campaigns.length} campanhas realizadas</span></div><div class="lists-grid">${ls.map(l=>`<article class="panel list-card"><div class="flex between"><span class="list-icon">${icon('users')}</span>${badge(l.category,'gold')}</div><h2>${esc(l.name)}</h2><p>${esc(l.description)}</p><footer><small>${l.contacts.length} contatos · ${l.contacts.filter(id=>!state.contacts.find(c=>c.id===id)?.optOut).length} elegíveis</small>${button('Abrir lista','list-detail',l.id,'quiet','arrow')}</footer></article>`).join('')||empty('Nenhuma lista encontrada.')}</div><section class="panel" style="margin-top:26px"><div class="panel-header"><div><h2>Campanhas de relacionamento</h2><p>Mensagens e destinatários registrados na linha do tempo</p></div>${icon('mail')}</div>${state.campaigns.length?`<div class="table-wrap"><table><thead><tr><th>Assunto</th><th>Destinatários</th><th>Data</th><th></th></tr></thead><tbody>${state.campaigns.map(c=>`<tr><td>${esc(c.subject)}</td><td>${c.contacts.length} contatos</td><td>${time(c.at)}</td><td>${button('Ver mensagem','campaign-detail',c.id,'quiet')}</td></tr>`).join('')}</tbody></table></div>`:empty('Sua próxima mensagem pode iniciar uma bonita história. Crie uma campanha para começar.')}</section>`}
function paymentTable(ps,compact=false){return ps.length?`<div class="table-wrap"><table><thead><tr><th>Doador</th><th>Valor</th><th>${compact?'Modalidade':'Data / competência'}</th>${compact?'':'<th>Destinação</th>'}<th></th></tr></thead><tbody>${ps.map(p=>{const c=state.contacts.find(c=>c.id===p.contactId);return `<tr><td>${contactCell(c)}</td><td style="color:var(--dark);font-weight:600">${money(p.amount)}</td><td>${compact?badge(p.mode,p.mode==='Pontual'?'gold':''):date(p.date)+`<small style="display:block">${monthLabel(p.period)} · ${p.mode}</small>`}</td>${compact?'':`<td>${esc(p.destination)}</td>`}<td><button class="icon-button" data-action="receipt" data-id="${p.id}" title="Ver recibo" aria-label="Ver recibo ${p.receipt}">${icon('file')}</button></td></tr>`}).join('')}</tbody></table></div>`:empty('Nenhuma contribuição encontrada neste período.')}
function finance(){const ps=state.payments.filter(p=>(!filters.period||p.date.startsWith(filters.period))&&(!filters.mode||p.mode===filters.mode)&&(!filters.q||state.contacts.find(c=>c.id===p.contactId)?.name.toLowerCase().includes(filters.q.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date)),pending=D.pending(state).filter(p=>(!filters.period||p.period===filters.period)&&(!filters.q||p.name.toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.status||p.overdue));return heading('Contribuições que transformam','Recebimentos via Pix, baixas mensais e cuidado com cada contribuição.',button('Exportar','export-finance','','secondary','download')+button('Registrar doação','payment','','','plus'))+`<section class="metrics">${metric('Recebido neste mês',money(total(paymentsFor())),'Doações financeiras confirmadas','wallet')}${metric('Recorrentes neste mês',money(total(paymentsFor().filter(p=>p.mode==='Recorrente'))),'Compromissos que viram cuidado','heart')}${metric('Pontuais neste mês',money(total(paymentsFor().filter(p=>p.mode==='Pontual'))),'Gestos de generosidade','leaf')}${metric('Saldo pendente',money(total(D.pending(state))),D.pending(state).length+' competências abertas','clock',true)}</section><div class="tabs"><button class="tab ${financeTab==='payments'?'active':''}" data-action="finance-tab" data-id="payments">Recebimentos</button><button class="tab ${financeTab==='pending'?'active':''}" data-action="finance-tab" data-id="pending">Pendências mensais ${badge(D.pending(state).length,'gold')}</button></div><div class="filters"><div class="search">${icon('search')}<input id="search" type="search" placeholder="Buscar um doador…" aria-label="Buscar doador" value="${esc(filters.q)}"></div><input type="month" name="period" value="${esc(filters.period)}" aria-label="Mês de recebimento ou competência">${financeTab==='payments'?select('mode',['Recorrente','Pontual'],filters.mode,'Todas as modalidades'):select('status',[['overdue','Somente em atraso']],filters.status,'Todas as pendências')}${Object.values(filters).some(Boolean)?button('Limpar filtros','clear','','quiet'):''}</div><section class="panel">${financeTab==='payments'?paymentTable(ps):pending.length?`<div class="table-wrap"><table><thead><tr><th>Doador</th><th>Competência</th><th>Vencimento</th><th>Saldo a receber</th><th>Situação</th><th></th></tr></thead><tbody>${pending.map(p=>`<tr><td>${contactCell(state.contacts.find(c=>c.id===p.contactId))}</td><td>${monthLabel(p.period)}</td><td>${date(p.due)}</td><td>${money(p.amount)}</td><td>${badge(p.overdue?'Em atraso':'A vencer',p.overdue?'red':'gold')}</td><td>${button('Dar baixa','payment-pending',p.contactId+'|'+p.period,'secondary small','check')}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma pendência encontrada. Obrigado por cultivar esses laços.')}</section>`}
function reports(){const {period,payments:ps,contacts:cs}=D.reportData(state,filters);return heading('O cuidado também se mede','Indicadores calculados a partir das contribuições e dos relacionamentos.',button('Exportar CSV','export-report','','secondary','download')+button('Exportar PDF','report-pdf','','secondary','file'))+`<div class="filters"><span class="filter-label">Período de análise</span><input type="month" name="period" value="${period}" aria-label="Período de análise">${select('mode',['Recorrente','Pontual'],filters.mode,'Todas as modalidades')}${select('stage',D.STAGES.map((s,i)=>[i,s]),filters.stage,'Todas as etapas')}</div><section class="metrics">${metric('Total arrecadado',money(total(ps)),ps.length+' lançamentos no período','wallet')}${metric('Doações recorrentes',money(total(ps.filter(p=>p.mode==='Recorrente'))),ps.filter(p=>p.mode==='Recorrente').length+' contribuições','heart')}${metric('Doações pontuais',money(total(ps.filter(p=>p.mode==='Pontual'))),ps.filter(p=>p.mode==='Pontual').length+' contribuições','leaf')}${metric('Conversão em doadores',(cs.filter(c=>c.plan&&c.plan.since<=period).length/Math.max(1,cs.length)*100).toFixed(1)+'%',cs.filter(c=>c.plan&&c.plan.since<=period).length+' doadores / '+cs.length+' contatos','chart',true)}</section><div class="report-grid"><section class="panel"><div class="panel-header"><div><h2>Recursos que chegam à comunidade</h2><p>Distribuição das doações por destinação</p></div></div><div class="panel-body">${D.DESTINATIONS.map(dest=>{const sum=total(ps.filter(p=>p.destination===dest));return `<div class="funnel-row"><div class="info">${dest}<div class="progress"><i style="width:${sum/Math.max(1,total(ps))*100}%"></i></div></div><strong style="font-size:13px">${money(sum)}</strong></div>`}).join('')}</div></section><section class="panel"><div class="panel-header"><div><h2>Avanço dos contatos cadastrados no período</h2><p>Etapas atuais e histórico disponível; não representa conversão histórica fechada. Modalidade filtra somente recebimentos.</p></div></div><div class="panel-body">${D.STAGES.map((stage,i)=>{const reached=cs.filter(c=>c.stage>=i||c.history.some(h=>h.action==='Etapa alterada'&&h.details.startsWith(stage)&&D.month(h.at)<=period)),converted=reached.filter(c=>i===3?c.plan&&c.plan.since<=period:c.stage>i||c.plan&&c.plan.since<=period||c.history.some(h=>h.action==='Etapa alterada'&&D.month(h.at)<=period&&D.STAGES.slice(i+1).some(t=>h.details.startsWith(t))));return `<div class="funnel-row"><div class="info">${esc(stage)}<small style="display:block;margin-top:5px">${converted.length} de ${reached.length} contatos${i===3?' tornaram-se doadores':' avançaram'}</small></div><strong>${(converted.length/Math.max(1,reached.length)*100).toFixed(0)}%</strong></div>`}).join('')}</div></section></div><section class="panel" style="margin-top:22px"><div class="panel-header"><div><h2>Contribuições do período</h2><p>Valores vinculados aos lançamentos financeiros</p></div><span class="badge">${monthLabel(period)}</span></div>${paymentTable(ps)}</section>`}
function users(){return heading('Pessoas que cuidam da nossa missão','Administre o acesso da equipe e os papéis de cada operador.',button('Novo usuário','user','','','plus'))+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Nome e e-mail</th><th>Perfil de acesso</th><th>Status</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td><div class="contact-cell">${avatar(u)}<div>${esc(u.name)}<small>${esc(u.email)}</small></div></div></td><td>${badge(u.role,u.role==='Administrador'?'gold':'')}</td><td>${badge(u.active?'Ativo':'Inativo',u.active?'':'gray')}</td><td>${button('Editar','user',u.id,'quiet','edit')}</td></tr>`).join('')}</tbody></table></div></section><div class="notice green" style="margin-top:22px">Administradores têm acesso completo. Operadores de captação cuidam dos contatos, das listas, dos relacionamentos e dos lançamentos de doações.</div>`}
function auditPage(){const entries=state.audit.filter(e=>!filters.q||(e.actorName+' '+e.action+' '+e.details).toLowerCase().includes(filters.q.toLowerCase()));return heading('Uma história que fica registrada','Rastreabilidade dos cadastros, relacionamentos e contribuições.')+`<div class="filters"><div class="search">${icon('search')}<input id="search" type="search" aria-label="Buscar na auditoria" placeholder="Buscar ação ou responsável…" value="${esc(filters.q)}"></div></div><section class="panel">${entries.length?`<div class="table-wrap"><table><thead><tr><th>Quando</th><th>Responsável</th><th>Ação</th><th>Detalhes</th></tr></thead><tbody>${entries.slice(0,100).map(e=>`<tr><td>${time(e.at)}</td><td>${esc(e.actorName)}</td><td>${esc(e.action)}</td><td style="max-width:380px;white-space:normal">${esc(e.details)}</td></tr>`).join('')}</tbody></table></div>`:empty('As ações da equipe aparecerão aqui.')}</section>`}
function renderLogin(){const token=new URLSearchParams(location.hash.slice(1)).get('redefinir');$('#app').innerHTML=`<div class="login"><section class="login-story">${brand()}<div><div class="eyebrow" style="margin-top:50px">Relacionamentos que transformam</div><h1>A esperança floresce quando cuidamos dos nossos laços.</h1><p>Um espaço para acolher, cultivar relacionamentos e acompanhar cada gesto de generosidade.</p><div class="art">${art()}</div></div><footer>Centro Espírita e Obras Sociais · Parnaíba, PI</footer></section><section class="login-content"><div class="login-theme">${themeButton()}</div><div class="login-form"><div class="eyebrow">Bem-vindo ao nosso espaço</div><h2>${token?'Uma nova senha':'Que bom ter você aqui.'}</h2><p>${token?'Escolha uma senha para voltar a cuidar dos nossos laços.':'Entre para acompanhar os relacionamentos e contribuições da nossa comunidade.'}</p><form id="auth-form"><div class="error" role="alert"></div>${token?field('Nova senha','password','','password','required minlength="8" autocomplete="new-password"')+field('Confirme a nova senha','confirm','','password','required minlength="8" autocomplete="new-password"'):field('Seu e-mail','email','','email','required autocomplete="username"')+field('Sua senha','password','','password','required autocomplete="current-password"')}<button class="btn" type="submit">${token?'Salvar nova senha':'Entrar no nosso espaço'} ${icon('arrow')}</button></form>${token?'':`<div style="text-align:right;margin-top:14px"><button class="text-link" data-action="recover">Esqueci minha senha</button></div><div class="demo"><p>Explore o protótipo com uma conta de demonstração.</p><div class="demo-buttons">${button('Administrador','demo','admin','secondary','shield')}${button('Operador','demo','operator','secondary','users')}</div><small style="display:block;margin-top:12px">Senha das contas de demonstração: <b>Esperanca@2026</b></small></div>`}<div class="login-bottom">Ambiente de demonstração · Dados fictícios</div></div></section></div>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,btn=$('button[type=submit]',f);btn.disabled=true;try{const d=Object.fromEntries(new FormData(f));if(token){const r=state.resets.find(r=>r.token===token&&!r.used&&r.expires>Date.now());if(!r)throw Error('Link de recuperação inválido ou expirado. Solicite outro.');if(d.password!==d.confirm)throw Error('As senhas precisam ser iguais.');const u=state.users.find(u=>u.id===r.userId);Object.assign(u,await credentials(d.password));r.used=true;D.audit(state,u,'Senha redefinida',null,'Recuperação de acesso');save();location.hash='';renderLogin();toast('Senha redefinida. Você já pode entrar.');return}if(Date.now()<lockUntil)throw Error('Aguarde um minuto antes de tentar novamente.');const u=state.users.find(u=>u.email.toLowerCase()===d.email.trim().toLowerCase()&&u.active);if(!u||await hashPassword(d.password,u.salt)!==u.passwordHash){loginAttempts++;if(loginAttempts>=5){lockUntil=Date.now()+60000;loginAttempts=0}throw Error('E-mail ou senha inválidos, ou usuário inativo.')}user=u;loginAttempts=0;lastActivity=Date.now();sessionStorage.setItem(SESSION,JSON.stringify({id:u.id,last:lastActivity}));page=u.role==='Administrador'?'dashboard':'funnel';D.audit(state,user,'Acesso ao sistema',null,'Sessão iniciada');D.reconcile(state,{id:'system',name:'Sistema'});D.ensureAutomations(state);save();render()}catch(err){$('.error',f).textContent=err.message;btn.disabled=false}}}
function bindPage(){const all=$('[data-action=select-filtered]');if(all){const eligible=visibleContacts().filter(emailEligible);all.indeterminate=!all.checked&&eligible.some(c=>selectedContacts.has(c.id))}const search=$('#search');if(search)search.addEventListener('input',e=>{filters.q=e.target.value;contactPage=1;const pos=e.target.selectionStart;$('#main').innerHTML=content()+pageFooter();bindPage();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos)});$$('.filters select,.filters input[type=month]').forEach(el=>el.onchange=()=>{filters[el.name]=el.value;contactPage=1;render()});$$('.card[draggable=true]').forEach(el=>el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.contact);e.dataTransfer.effectAllowed='move'});$$('.column[data-stage]').forEach(el=>{el.ondragover=e=>{e.preventDefault();el.classList.add('over')};el.ondragleave=()=>el.classList.remove('over');el.ondrop=e=>{e.preventDefault();el.classList.remove('over');try{activeUser();D.move(state,user,e.dataTransfer.getData('text/plain'),Number(el.dataset.stage));save();render();toast('Etapa atualizada no histórico.')}catch(err){toast(err.message,'error')}}})}
let returnFocus;
function closeModal(){const m=$('#modal');if(m.open)m.close();m.innerHTML='';m.classList.remove('wide');returnFocus?.focus()}
function modal(title,body,footer='',wide=false){returnFocus=document.activeElement;const m=$('#modal');m.classList.toggle('wide',wide);m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button type="button" class="icon-button" data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;if(!m.open)m.showModal();m.scrollTop=0}
function formModal(title,body,onSubmit,label='Salvar',wide=false,auth=false){modal(title,`<form id="modal-form"><div class="error" role="alert"></div>${body}<div class="modal-foot" style="margin:12px -28px -24px">${button('Cancelar','close')}<button type="submit" class="btn">${label} ${icon('check')}</button></div></form>`,'',wide);$('#modal-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,submit=$('[type=submit]',f);submit.disabled=true;try{if(!auth)activeUser();await onSubmit(Object.fromEntries(new FormData(f)),f)}catch(err){$('.error',f).textContent=err.message;submit.disabled=false}}}
function contactForm(id='',draft=null){const existing=state.contacts.find(c=>c.id===id),c=draft||existing||{name:'',email:'',phone:'',type:'PF',document:'',origin:'Indicação',funnel:'Inbound',stage:0,owner:user.id};formModal(existing?'Editar relacionamento':'Um novo relacionamento',`<div class="step-label">1 de 2 · Conhecer a pessoa</div><div class="form-grid">${field('Nome completo / razão social *','name',c.name,'text','required maxlength="120"')}${selectField('Tipo de pessoa','type',[['PF','Pessoa física'],['PJ','Pessoa jurídica']],c.type)}${field('E-mail','email',c.email,'email','maxlength="150"')}${field('Telefone / WhatsApp','phone',c.phone,'tel','maxlength="16" placeholder="(86) 99999-9999"')}${field('CPF / CNPJ (opcional)','document',c.document,'text','inputmode="numeric" maxlength="18"')}<div class="full"><small>Informe pelo menos um e-mail ou telefone para mantermos esse laço.</small></div></div>`,d=>{const merged={...c,...d};D.validateContact(merged,state.contacts,id,true);contactStepTwo(id,merged)},'Continuar');const phone=$f('[name=phone]'),doc=$f('[name=document]');phone.oninput=()=>{let n=phone.value.replace(/\D/g,'').slice(0,11);phone.value=n.replace(/^(\d{2})(\d)/,'($1) $2').replace(/(\d{4,5})(\d{4})$/,'$1-$2')};doc.oninput=()=>{const n=doc.value.replace(/\D/g,'').slice(0,$f('[name=type]').value==='PF'?11:14);doc.value=$f('[name=type]').value==='PF'?n.replace(/^(\d{3})(\d)/,'$1.$2').replace(/^(\d{3})\.(\d{3})(\d)/,'$1.$2.$3').replace(/(\d{3})(\d{2})$/,'$1-$2'):n.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/,'$1.$2.$3').replace(/(\d{3})(\d{4})/,'$1/$2').replace(/(\d{4})(\d{2})$/,'$1-$2')};$f('[name=type]').onchange=()=>doc.oninput()}
function contactStepTwo(id,c){formModal('Onde começa esse caminho?',`<div class="step-label">2 de 2 · Origem e relacionamento</div><div class="notice green">${esc(c.name)} · ${esc(c.email||c.phone)}</div><div class="form-grid">${selectField('Origem','origin',D.ORIGINS,c.origin)}${selectField('Classificação','funnel',['Inbound','Outbound'],c.funnel)}${selectField('Etapa inicial','stage',D.STAGES.map((s,i)=>[i,s]),c.stage)}${user.role==='Administrador'?selectField('Operador responsável','owner',state.users.filter(u=>u.active).map(u=>[u.id,u.name]),c.owner):''}</div>${button('Voltar aos dados','contact-back',id,'quiet')}`,d=>{const merged={...c,...d,funnel:['Site','Instagram'].includes(d.origin)?'Inbound':d.funnel,stage:Number(d.stage),owner:d.owner||c.owner};D.validateContact(merged,state.contacts,id);const existing=state.contacts.find(c=>c.id===id);if(existing){if(D.outsideCadence(existing)&&merged.stage!==existing.stage)throw Error('Retome a cadência antes de mover a etapa.');const oldStage=existing.stage;if(existing.origin!==merged.origin||existing.funnel!==merged.funnel)D.audit(state,user,'Origem e direção alteradas',id,existing.origin+' / '+existing.funnel+' → '+merged.origin+' / '+merged.funnel);Object.assign(existing,merged,{stage:oldStage});D.move(state,user,id,merged.stage);D.audit(state,user,'Cadastro atualizado',id)}else{merged.id=D.uid();merged.created=new Date().toISOString();merged.history=[];merged.optOut=false;state.contacts.unshift(merged);save();D.audit(state,user,'Contato cadastrado',merged.id,merged.origin+' · '+merged.funnel)}save();closeModal();render();profile(existing?.id||merged.id);toast('Relacionamento salvo com carinho.')} ,'Salvar contato');$('[data-action=contact-back]').onclick=e=>{e.stopPropagation();contactForm(id,c)};bindOriginDirection()}
function profile(id){const c=state.contacts.find(c=>c.id===id);if(!c)throw Error('Contato não encontrado.');const ps=state.payments.filter(p=>p.contactId===id);modal('Ficha de relacionamento',`<div class="profile-hero">${avatar(c)}<div><h2>${esc(c.name)}</h2><p style="margin-top:7px">${statusBadge(c)} ${badge(c.type,'gold')}  ${c.optOut?badge('Descadastrado de e-mails','gray'):''}</p></div></div><div class="profile-grid"><div><dl class="details"><div><dt>E-mail</dt><dd>${esc(c.email||'Não informado')}</dd></div><div><dt>Telefone</dt><dd>${esc(c.phone||'Não informado')}</dd></div><div><dt>CPF / CNPJ</dt><dd>${esc(c.document||'Não informado')}</dd></div><div><dt>Origem</dt><dd>${esc(c.origin)} · ${c.funnel}</dd></div><div><dt>Responsável</dt><dd>${esc(state.users.find(u=>u.id===c.owner)?.name||'—')}</dd></div><div><dt>Desde</dt><dd>${date(c.created)}</dd></div></dl><div class="notice green"><small>Etapa atual</small><p>${D.STAGES[c.stage]}</p>${D.outsideCadence(c)?`<p>Etapa de perdas: ${esc(D.LOSS_STAGES[D.lossStage(c)])}</p>${c.cadenceExit.followUpDate?`<p>Retomada agendada: ${date(c.cadenceExit.followUpDate)}</p>`:''}<p><b>Fora da cadência</b> · ${esc(c.cadenceExit.reason)}</p><p>${esc(c.cadenceExit.note)}</p><p>Saída: ${date(c.cadenceExit.date)} · ${esc(c.cadenceExit.actorName)}</p><p>Última etapa: ${esc(D.STAGES[c.cadenceExit.stage])}</p>`:''}${c.plan?`<p style="margin-top:10px">Compromisso: <b>${money(c.plan.amount)}</b> · ${c.plan.mode}${c.plan.due?' · Dia '+c.plan.due:''}</p>`:''}</div>${enrollmentInfo(c)}${intakeSummary(c)}${contactTasks(c)}<div class="profile-actions">${button('Editar','contact',id,'secondary small','edit')}${D.outsideCadence(c)?button('Mover etapa de perdas','loss-move',id,'secondary small')+button('Retomar cadência','cadence-resume',id,'secondary small'):button('Registrar perda','cadence-exit',id,'secondary small')}${!c.plan&&!D.outsideCadence(c)?button('Mover etapa','move',id,'secondary small','funnel')+button('Converter em doador','convert',id,'small','heart'):c.plan?button('Registrar doação','payment',id,'small','plus')+button('Alterar status','donor-status',id,'secondary small'):''}${button('Registrar interação','interaction',id,'secondary small','plus')}${button('Registrar resposta','response',id,'secondary small','mail')}${c.plan?button('Comprovante de adesão','adherence',id,'quiet small','file'):''}${!c.optOut&&c.email?button('Enviar mensagem','contact-mail',id,'quiet small','mail'):''}${user.role==='Administrador'?button('Excluir contato','delete-contact',id,'danger small'):''}</div>${ps.length?`<h3 style="margin:22px 0 8px">Contribuições · ${money(total(ps))}</h3>${ps.slice(0,4).map(p=>`<div class="list-row"><div><p>${money(p.amount)}</p><small>${date(p.date)} · ${monthLabel(p.period)}</small></div><button class="icon-button right" data-action="receipt" data-id="${p.id}" aria-label="Ver recibo">${icon('file')}</button></div>`).join('')}`:''}</div><div><div class="flex between" style="margin-bottom:22px"><h3>Uma história de relacionamento</h3><small>${c.history.length} registros</small></div><div class="timeline">${c.history.map(e=>`<article class="event"><h3>${esc(e.action)}</h3><p>${esc(e.details)}</p><small>${time(e.at)} · ${esc(e.actorName)}</small></article>`).join('')}</div></div></div>`,'',true)}
function moveForm(id){const c=state.contacts.find(c=>c.id===id);formModal('Um novo passo no relacionamento',`<p class="muted" style="margin-bottom:20px">${esc(c.name)}</p>${selectField('Próxima etapa','stage',D.STAGES.map((s,i)=>[i,s]),c.stage)}<div class="field"><label for="f-note">Anotações da mudança</label><textarea id="f-note" name="note" placeholder="O que motivou este novo passo?" maxlength="1500"></textarea></div>`,d=>{D.move(state,user,id,Number(d.stage),d.note);save();closeModal();render();toast('Etapa atualizada e registrada no histórico.')},'Atualizar etapa')}
function convertForm(id){const c=state.contacts.find(c=>c.id===id);formModal('Um novo gesto de generosidade',`<div class="notice green">${esc(c.name)} passará a fazer parte da nossa rede de doadores.</div>${selectField('Modalidade de contribuição','mode',['Recorrente','Pontual'],'Recorrente')}${field('Valor compromissado (R$) *','amount',100,'number','required min="0.01" max="999999999" step="0.01"')}${field('Dia do vencimento mensal *','due',10,'number','required min="1" max="28" step="1"')}<small>O comprovante de adesão será gerado após a conversão.</small>`,d=>{D.convert(state,user,id,{mode:d.mode,amount:Number(d.amount),due:Number(d.due)});save();closeModal();render();adherence(id);toast('Contato convertido em doador ativo.')},'Confirmar adesão');$f('[name=mode]').onchange=()=>{const input=$f('[name=due]'),recurring=$f('[name=mode]').value==='Recorrente';input.closest('.field').hidden=!recurring;input.required=recurring;input.disabled=!recurring}}
function adherence(id){const c=state.contacts.find(c=>c.id===id);modal('Comprovante de adesão',`<div class="receipt">${brand()}<div class="eyebrow">Cuidar, contribuir, transformar</div><h2>Compromisso de contribuição</h2><p>${esc(c.name)} · ${esc(c.email||c.phone)}</p><strong class="amount">${money(c.plan.amount)}</strong><dl class="details"><div><dt>Modalidade</dt><dd>${c.plan.mode}</dd></div><div><dt>Adesão</dt><dd>${monthLabel(c.plan.since)}</dd></div><div><dt>Vencimento</dt><dd>${c.plan.due?'Todo dia '+c.plan.due:'Contribuição única'}</dd></div><div><dt>Situação</dt><dd>${c.plan.status}</dd></div></dl><p>Obrigado por caminhar com a Luz da Esperança.</p><small>Comprovante de adesão · Não representa confirmação de pagamento.</small></div>`,button('Fechar','close')+button('Imprimir / salvar PDF','print','','','download'))}
function interactionForm(id){formModal('Cultive esse relacionamento',`${selectField('Como foi o contato?','channel',['Telefone','WhatsApp','Reunião','E-mail'],'WhatsApp')}${field('Data e hora do contato','date',new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16),'datetime-local','required')}<div class="field"><label for="f-summary">Resumo da conversa *</label><textarea id="f-summary" name="summary" required maxlength="3000" placeholder="Conte o que foi conversado e os próximos passos."></textarea></div><small>Este registro preserva o histórico e identifica o operador responsável.</small>`,d=>{if(new Date(d.date)>new Date())throw Error('A data do contato não pode ser futura.');if(!d.summary.trim())throw Error('Informe o resumo da conversa.');D.audit(state,user,'Contato por '+d.channel,id,d.summary+'\nData do contato: '+time(d.date));save();closeModal();render();profile(id);toast('Interação registrada no histórico.')},'Registrar interação')}
function responseForm(id){formModal('Escutar também faz parte',`${selectField('Classificação da resposta','classification',['Positiva','Negativa','Pedido de descadastro'],'Positiva')}<div class="field"><label for="f-message">Conteúdo da resposta *</label><textarea id="f-message" name="message" required maxlength="3000" placeholder="Registre a resposta recebida."></textarea></div>`,d=>{if(!d.message.trim())throw Error('Informe o conteúdo da resposta.');const c=state.contacts.find(c=>c.id===id);if(d.classification==='Pedido de descadastro')c.optOut=true;D.audit(state,user,'Resposta de e-mail: '+d.classification,id,d.message);save();closeModal();render();profile(id);toast(d.classification==='Pedido de descadastro'?'Descadastro registrado. Novos envios serão bloqueados.':'Resposta registrada.')},'Registrar resposta')}
function statusForm(id){const c=state.contacts.find(c=>c.id===id);formModal('Cuidar do ciclo do doador',`${selectField('Novo status','status',D.DONOR_STATUSES,c.plan.status)}${field('Data do evento','date',D.today(),'date',`required max="${D.today()}"`)}<p class="notice">Suspenso interrompe competências cujo vencimento ocorre entre a suspensão (inclusive) e a retomada (exclusive). Débitos anteriores permanecem. Recebimentos não reativam automaticamente o doador.</p><div class="field"><label for="f-reason">Motivo da alteração *</label><textarea id="f-reason" name="reason" required maxlength="2000"></textarea></div>`,d=>{if(d.date>D.today())throw Error('A data não pode ser futura.');if(!d.reason.trim())throw Error('Informe o motivo.');D.changeStatus(state,user,id,d);save();closeModal();render();profile(id);toast('Status atualizado e histórico preservado.')},'Atualizar status')}
function paymentForm(id='',period='',draft=null){const c=state.contacts.find(c=>c.id===id),pending=D.pending(state).find(p=>p.contactId===id&&p.period===period),d=draft||{contactId:id,amount:pending?.amount||c?.plan?.amount||'',date:D.today(),period:period||D.month(),destination:'Obras sociais'};formModal('Registrar doação recebida',`<div class="step-label">1 de 2 · Doação já recebida</div><div class="form-grid">${selectField('Doador *','contactId',state.contacts.filter(c=>c.plan).map(c=>[c.id,c.name]),d.contactId,'Selecione um doador')}${field('Valor recebido (R$) *','amount',d.amount,'number','required min="0.01" max="999999999" step="0.01"')}${field('Data do pagamento *','date',d.date,'date','required max="'+D.today()+'"')}${field('Competência mensal *','period',d.period,'month','required')}${selectField('Destinação do recurso','destination',D.DESTINATIONS,d.destination)}<div class="full"><small>Informe o valor que já foi efetivamente recebido, em reais, e a data do pagamento. Este registro gera o recebimento e o recibo da doação.</small></div></div>`,data=>{if(!data.contactId)throw Error('Selecione um doador.');if(Number(data.amount)<=0)throw Error('Informe um valor maior que zero.');paymentStepTwo({...data,amount:Number(data.amount)})},'Continuar');const pick=$f('[name=contactId]');pick.required=true;pick.onchange=()=>{const donor=state.contacts.find(c=>c.id===pick.value);if(donor){$f('[name=amount]').value=donor.plan.amount;$f('[name=period]').min=donor.plan.since;$f('[name=period]').closest('.field').hidden=donor.plan.mode==='Pontual';$f('[name=period]').required=donor.plan.mode==='Recorrente'}};if(c){$f('[name=period]').min=c.plan.since;$f('[name=period]').closest('.field').hidden=c.plan.mode==='Pontual';$f('[name=period]').required=c.plan.mode==='Recorrente'}}
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve({name:file.name,type:file.type,data:r.result});r.onerror=()=>reject(Error('Não foi possível ler o arquivo.'));r.readAsDataURL(file)})}
function paymentStepTwo(d){formModal('Vincule o comprovante',`<div class="step-label">2 de 2 · Identificação do recebimento</div><div class="notice green">${esc(state.contacts.find(c=>c.id===d.contactId).name)} · <b>${money(d.amount)}</b> · ${date(d.date)}</div>${field('Código / referência Pix','pix','','text','maxlength="180" placeholder="Identificador do recebimento"')}${field('Comprovante (opcional)','attachment','','file','accept="image/png,image/jpeg,application/pdf"')}<small>Informe a referência Pix ou anexe um comprovante (PNG, JPG ou PDF, até 2 MB).</small><div style="margin-top:14px">${button('Voltar à contribuição','payment-back','','quiet')}</div>`,async(data,f)=>{const file=$f('[name=attachment]',f).files[0];if(file&&(file.size>2*1024*1024||!['image/png','image/jpeg','application/pdf'].includes(file.type)))throw Error('Anexe PNG, JPG ou PDF de até 2 MB.');const attachment=file?await fileData(file):null,p=D.payment(state,user,{...d,pix:data.pix,attachment});save();closeModal();render();receipt(p.id);toast('Doação registrada. Pendência e indicadores atualizados.')},'Confirmar recebimento');$('[data-action=payment-back]').onclick=e=>{e.stopPropagation();paymentForm(d.contactId,d.period,d)}}
function receipt(id){const p=state.payments.find(p=>p.id===id),c=state.contacts.find(c=>c.id===p.contactId);modal('Recibo de contribuição',`<div class="receipt">${brand()}<div class="eyebrow">${p.receipt}</div><h2>Obrigado por espalhar esperança.</h2><p>Recebemos de <b>${esc(c.name)}</b> uma contribuição financeira para apoiar nossas obras sociais.</p><strong class="amount">${money(p.amount)}</strong><dl class="details"><div><dt>Data do pagamento</dt><dd>${date(p.date)}</dd></div><div><dt>Competência</dt><dd>${monthLabel(p.period)}</dd></div><div><dt>Modalidade</dt><dd>${p.mode}</dd></div><div><dt>Destinação</dt><dd>${esc(p.destination)}</dd></div><div><dt>Referência Pix</dt><dd>${esc(p.pix||'Comprovante anexo')}</dd></div><div><dt>Responsável pelo registro</dt><dd>${esc(p.actorName)} · ${time(p.at)}</dd></div></dl>${p.attachment?button('Baixar comprovante · '+esc(p.attachment.name),'attachment',p.id,'secondary small','download'):''}<p>Centro Espírita e Obras Sociais Luz da Esperança<br>Parnaíba, PI</p><small>Recibo emitido no ambiente de demonstração com dados fictícios.</small></div>`,button('Fechar','close')+button('Enviar por e-mail','receipt-email',id,'secondary','mail')+button('Imprimir / salvar PDF','print','','','download'))}
function listForm(id=''){const l=state.lists.find(l=>l.id===id);formModal(l?'Editar lista':'Uma nova rede de conexões',`${field('Nome da lista *','name',l?.name||'','text','required maxlength="120"')}${field('Categoria dos contatos *','category',l?.category||'','text','required maxlength="80"')}<div class="field"><label for="f-description">Descrição da lista</label><textarea id="f-description" name="description" maxlength="1500">${esc(l?.description||'')}</textarea></div>`,d=>{if(!d.name.trim()||!d.category.trim())throw Error('Informe nome e categoria.');if(l)Object.assign(l,d);else state.lists.unshift({...d,id:D.uid(),contacts:[],imports:[]});D.audit(state,user,l?'Lista atualizada':'Lista criada',null,d.name);save();closeModal();render();toast('Lista salva.')},'Salvar lista')}
function listDetail(id){const l=state.lists.find(l=>l.id===id);modal(esc(l.name),`<p class="muted" style="margin-bottom:20px">${esc(l.description)}</p><div class="flex" style="flex-wrap:wrap;margin-bottom:20px">${button('Importar CSV / Excel','import',id,'','upload')}${button('Adicionar contatos','list-contacts',id,'secondary','plus')}${button('Criar campanha','campaign',id,'secondary','mail')}${button('Editar lista','list',id,'quiet','edit')}</div><div class="table-wrap"><table><thead><tr><th>Contato</th><th>Envios</th><th></th></tr></thead><tbody>${l.contacts.map(id=>state.contacts.find(c=>c.id===id)).filter(Boolean).map(c=>`<tr><td>${contactCell(c)}</td><td>${badge(c.optOut?'Descadastrado':c.email?'Elegível':'Sem e-mail',c.optOut?'gray':'')}</td><td><button class="icon-button" data-action="remove-list-contact" data-id="${l.id+'|'+c.id}" aria-label="Remover da lista">${icon('close')}</button></td></tr>`).join('')}</tbody></table></div>${!l.contacts.length?empty('Importe um arquivo ou adicione contatos da sua rede.') :''}${l.imports.length?`<h3 style="margin:22px 0 10px">Última importação</h3><div class="notice green">${l.imports[0].imported} importados · ${l.imports[0].duplicates} duplicados · ${l.imports[0].invalid} inválidos</div>${l.imports[0].rows.length?`<details><summary>Ver registros descartados</summary><p style="font-size:11px;margin-top:10px">${l.imports[0].rows.map(esc).join('<br>')}</p></details>`:''}`:''}`,'',true)}
function enrollmentInfo(c){
 if(!D.enrolled(state,c))return '';
 const since=c.plan.adheredAt,days=since?Math.max(0,Math.floor((Date.now()-Date.parse(since))/86400000)):null;
 return `<p class="notice enrolled-alert"><b>Sócio Inscrito · Doador</b><br>Colabora com a Luz da Esperança. Nenhuma doação financeira registrada.<br>${since?'Adesão: '+date(since)+' · '+days+' dias desde a adesão':'Data de adesão não disponível'}</p>`;
}
function contactTasks(c){
 const ts=state.tasks.filter(t=>t.contactId===c.id);
 return ts.length?`<section class="contact-tasks"><h3>Acompanhamento</h3>${ts.map(t=>`<div class="list-row"><div><p>${esc(t.text)}</p><small>${t.due?'Prazo: '+date(t.due):date(t.at)} · ${esc(state.users.find(u=>u.id===t.owner)?.name||'Equipe')} · ${t.done?'Concluído':'Pendente'}</small></div>${!t.done?button('Concluir','task-done',t.id,'quiet small','check'):''}</div>`).join('')}</section>`:'';
}
