 $('[data-action=report-print-local]').onclick=e=>{e.stopPropagation();try{admin();D.audit(state,user,'Impressão de relatório solicitada',null,period+' · '+(filters.mode||'Todas as modalidades')+' · '+(filters.stage?D.STAGES[Number(filters.stage)]:'Todas as etapas'));save();window.print()}catch(err){toast(err.message,'error')}};
