function listContacts(id){
 const l=state.lists.find(l=>l.id===id),chosen=new Set();let current=[];
 formModal('Adicionar à nossa rede',`<p>${esc(l.name)}</p><div class="form-grid segment-filters">${field('Buscar nome ou e-mail','q','','search')}${selectField('Vínculo','link',[['donors','Doadores'],['leads','Potenciais doadores']],'','Todos os contatos')}${selectField('Status de doador','status',D.DONOR_STATUSES,'','Todos os status')}${selectField('Modalidade','mode',['Recorrente','Pontual'],'','Todas')}${selectField('Identificação','enrolled',[['yes','Sócio Inscrito']],'','Todas')}${selectField('Origem','origin',D.ORIGINS,'','Todas')}${selectField('Classificação','direction',['Inbound','Outbound'],'','Todas')}${selectField('Destinação recebida','destination',D.DESTINATIONS,'','Todas')}${field('Pagamento a partir de','start','','date')}${field('Pagamento até','end','','date')}</div><div class="selection-summary" aria-live="polite"></div><label class="select-filtered"><input type="checkbox" id="list-all"> Selecionar todos os resultados <span id="list-count"></span></label>${button('Limpar seleção','list-clear-local','','quiet small')}<div class="check-list" id="list-results"></div>`,()=>{if(!chosen.size)throw Error('Selecione pelo menos um contato.');const n=D.addToList(state,user,id,[...chosen]);save();closeModal();render();listDetail(id);toast(n+' contatos adicionados, sem duplicidades.')},'Adicionar contatos',true);
 const f=$('#modal-form'),results=$('#list-results'),all=$('#list-all');
 const summary=()=>{const n=current.filter(c=>chosen.has(c.id)).length;all.checked=current.length>0&&n===current.length;all.indeterminate=n>0&&n<current.length;all.disabled=!current.length;$('.selection-summary',f).textContent=chosen.size+' selecionados · '+([...chosen].filter(id=>!current.some(c=>c.id===id)).length)+' fora do resultado atual';$('#list-count').textContent='('+current.length+')'};
 const update=()=>{try{current=D.segmentContacts(state,Object.fromEntries(new FormData(f)),l.contacts);$('.error',f).textContent='';results.innerHTML=current.map(c=>`<label><input type="checkbox" value="${esc(c.id)}" ${chosen.has(c.id)?'checked':''}>${esc(c.name)} <small>${esc(c.plan?.status||'Potencial doador')}${D.enrolled(state,c)?' · Sócio Inscrito':''} · ${esc(c.email||c.phone)}</small></label>`).join('')||empty('Nenhum contato atende aos filtros.');results.querySelectorAll('input').forEach(el=>el.onchange=()=>{el.checked?chosen.add(el.value):chosen.delete(el.value);summary()});summary()}catch(e){current=[];results.innerHTML='';$('.error',f).textContent=e.message;summary()}};
 $$('.segment-filters input,.segment-filters select',f).forEach(el=>el.oninput=update);
 all.onchange=()=>{current.forEach(c=>all.checked?chosen.add(c.id):chosen.delete(c.id));update()};
 $('[data-action=list-clear-local]',f).onclick=e=>{e.stopPropagation();chosen.clear();update()};update();
}

async function excelRows(file){const buf=await file.arrayBuffer(),v=new DataView(buf),bytes=new Uint8Array(buf),files={};let eocd=-1;for(let i=v.byteLength-22;i>=Math.max(0,v.byteLength-65557);i--){if(v.getUint32(i,true)===0x06054b50){eocd=i;break}}if(eocd<0)throw Error('Excel inválido. Use .xlsx ou salve como CSV.');let pos=v.getUint32(eocd+16,true),count=v.getUint16(eocd+10,true),budget=0;for(let i=0;i<count;i++){if(v.getUint32(pos,true)!==0x02014b50)throw Error('Arquivo Excel inválido.');const method=v.getUint16(pos+10,true),size=v.getUint32(pos+20,true),rawSize=v.getUint32(pos+24,true),nameLen=v.getUint16(pos+28,true),extraLen=v.getUint16(pos+30,true),commentLen=v.getUint16(pos+32,true),offset=v.getUint32(pos+42,true),name=new TextDecoder().decode(bytes.slice(pos+46,pos+46+nameLen));pos+=46+nameLen+extraLen+commentLen;if(!/^xl\/(sharedStrings\.xml|worksheets\/sheet\d+\.xml)$/.test(name))continue;budget+=rawSize;if(budget>20*1024*1024)throw Error('Planilha muito grande. Importe até 20 MB de conteúdo descompactado.');const start=offset+30+v.getUint16(offset+26,true)+v.getUint16(offset+28,true),compressed=bytes.slice(start,start+size);let out;if(method===0)out=compressed;else if(method===8){try{out=new Uint8Array(await new Response(new Blob([compressed]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer())}catch{throw Error('Este navegador não lê o Excel comprimido. Use um navegador atualizado ou salve como CSV.')}}else throw Error('Compressão Excel não suportada. Salve como CSV.');files[name]=new TextDecoder().decode(out)}const parser=new DOMParser(),strings=files['xl/sharedStrings.xml']?[...parser.parseFromString(files['xl/sharedStrings.xml'],'application/xml').getElementsByTagName('si')].map(si=>[...si.getElementsByTagName('t')].map(t=>t.textContent).join('')):[];const sheet=Object.keys(files).filter(n=>n.includes('worksheets/')).sort()[0];if(!sheet)throw Error('Nenhuma planilha encontrada.');const xml=parser.parseFromString(files[sheet],'application/xml');if(xml.querySelector('parsererror'))throw Error('Planilha inválida.');return [...xml.getElementsByTagName('row')].map(row=>{const result=[];for(const c of row.getElementsByTagName('c')){const ref=c.getAttribute('r')||'A',col=[...ref.replace(/\d/g,'')].reduce((n,ch)=>n*26+ch.charCodeAt(0)-64,0)-1,type=c.getAttribute('t'),val=c.getElementsByTagName('v')[0]?.textContent||'';result[col]=type==='s'?strings[Number(val)]||'':type==='inlineStr'?[...c.getElementsByTagName('t')].map(t=>t.textContent).join(''):val}return result})}
function importForm(id){formModal('Novos laços para a nossa lista',`<div class="notice green">Importe CSV ou Excel (.xlsx) com as colunas <b>nome</b>, <b>email</b> e, opcionalmente, <b>telefone</b>. E-mails inválidos e duplicados serão descartados.</div>${field('Arquivo de contatos *','file','','file','required accept=".csv,.xlsx"')}${button('Baixar modelo CSV','csv-template','','quiet','download')}<small style="display:block;margin-top:12px">Até 5 MB por arquivo. O relatório da importação fica disponível na lista.</small>`,async(d,f)=>{const file=$('[name=file]',f).files[0];if(file.size>5*1024*1024)throw Error('O arquivo deve ter até 5 MB.');let rows;if(/\.xlsx$/i.test(file.name))rows=await excelRows(file);else if(/\.csv$/i.test(file.name))rows=D.parseCSV(await file.text());else throw Error('Use CSV ou Excel .xlsx.');if(rows.length>10001)throw Error('Importe até 10.000 contatos por arquivo.');const l=state.lists.find(l=>l.id===id),r=D.importRows(state,user,l,rows);save();closeModal();render();listDetail(id);toast(r.imported+' contatos importados · '+r.duplicates+' duplicados · '+r.invalid+' inválidos')},'Importar contatos')}
function campaignForm(listId='',contactId=''){if(!state.lists.length&&!contactId)throw Error('Crie uma lista de contatos antes da campanha.');formModal('Uma mensagem pode aproximar',`${contactId?`<div class="notice green">Para ${esc(state.contacts.find(c=>c.id===contactId).name)}</div>`:selectField('Lista de destinatários *','listId',state.lists.map(l=>[l.id,l.name]),listId||state.lists[0]?.id)}${field('Assunto da mensagem *','subject','','text','required maxlength="180"')}<div class="field"><label for="f-body">Mensagem *</label><textarea id="f-body" name="body" required maxlength="10000" rows="6" placeholder="Olá! Queremos compartilhar um pouco do que estamos construindo juntos…"></textarea></div><small>Contatos descadastrados ou sem e-mail ficam fora do envio.</small>`,d=>{const ids=contactId?[contactId]:state.lists.find(l=>l.id===d.listId).contacts;const eligible=ids.filter(id=>{const c=state.contacts.find(c=>c.id===id);return c?.email&&!c.optOut});if(!eligible.length)throw Error('Nenhum destinatário elegível nesta lista.');modal('Revise a mensagem',`<div class="notice green">${eligible.length} destinatário(s) elegível(is) · ${ids.length-eligible.length} excluído(s)</div><h3 style="margin-bottom:15px">${esc(d.subject)}</h3><div class="campaign-preview">${esc(d.body)}</div>`,button('Voltar','campaign-back')+button('Confirmar envio','campaign-send','','','mail'));$('[data-action=campaign-send]').onclick=e=>{e.stopPropagation();try{activeUser();const n=D.send(state,user,ids,d.subject,d.body);save();closeModal();render();toast(n+' mensagens registradas nas linhas do tempo.')}catch(err){toast(err.message,'error')}};$('[data-action=campaign-back]').onclick=e=>{e.stopPropagation();campaignForm(d.listId,contactId);$('[name=subject]').value=d.subject;$('[name=body]').value=d.body}},'Revisar mensagem')}
function userForm(id=''){admin();const u=state.users.find(u=>u.id===id);formModal(u?'Editar acesso':'Uma nova pessoa na equipe',`<div class="form-grid">${field('Nome completo *','name',u?.name||'','text','required maxlength="100"')}${field('E-mail de acesso *','email',u?.email||'','email','required maxlength="150"')}${selectField('Perfil de acesso','role',['Administrador','Operador de Captação'],u?.role||'Operador de Captação')}${selectField('Status','active',[['yes','Ativo'],['no','Inativo']],u?.active===false?'no':'yes')}${field(u?'Nova senha (opcional)':'Senha inicial *','password','','password',(u?'':'required ')+'minlength="8" autocomplete="new-password"')}<small>Use pelo menos 8 caracteres. Senhas são armazenadas por hash.</small></div>`,async d=>{admin();if(state.users.some(x=>x.id!==id&&x.email.toLowerCase()===d.email.toLowerCase()))throw Error('Este e-mail já possui acesso.');if(u?.id===user.id&&(d.role!=='Administrador'||d.active==='no'))throw Error('Você não pode remover seu próprio acesso administrativo.');if(u?.role==='Administrador'&&(d.role!=='Administrador'||d.active==='no')&&state.users.filter(x=>x.role==='Administrador'&&x.active&&x.id!==id).length===0)throw Error('Mantenha pelo menos um administrador ativo.');const update={name:d.name.trim(),email:d.email.trim(),role:d.role,active:d.active==='yes'};if(d.password)Object.assign(update,await credentials(d.password));if(u)Object.assign(u,update);else state.users.push({...update,id:D.uid()});D.audit(state,user,u?'Usuário atualizado':'Usuário cadastrado',null,d.name+' · '+d.role);save();closeModal();render();toast('Acesso da equipe atualizado.')},'Salvar acesso')}
function recover(){formModal('Vamos recuperar seu acesso',`<p class="muted" style="margin-bottom:20px">Informe o e-mail cadastrado para receber as instruções.</p>${field('E-mail de recuperação','email','','email','required')}`,d=>{const u=state.users.find(u=>u.email.toLowerCase()===d.email.trim().toLowerCase()&&u.active);if(!u){modal('Confira sua caixa de entrada','<p>Se o e-mail estiver cadastrado, você receberá as instruções de recuperação.</p>',button('Voltar ao acesso','close'));return}const token=D.uid();state.resets.push({token,userId:u.id,expires:Date.now()+15*60*1000,used:false});save();modal('Instruções de recuperação',`<div class="notice green">As instruções foram preparadas para ${esc(u.email)}.</div><p style="margin-bottom:16px">No protótipo, a entrega do e-mail é simulada. Use o link abaixo para testar a redefinição.</p><div class="campaign-preview">Olá, ${esc(u.name.split(' ')[0])}!<br>Você solicitou uma nova senha. Este link é válido por 15 minutos.</div><a class="btn" style="margin-top:20px" href="#redefinir=${token}" data-action="reset-link">Criar nova senha ${icon('arrow')}</a>`,button('Fechar','close'))},'Enviar instruções',false,true)}
function tasks(){modal('Cultivar nossos relacionamentos',state.tasks.filter(t=>!t.done).map(t=>`<div class="list-row"><div><h3>${esc(t.text)}</h3><small>${t.due?'Prazo: '+date(t.due):date(t.at)} · ${esc(state.users.find(u=>u.id===t.owner)?.name||'Equipe')} · ${t.intakeRunId?'Acompanhamento':'Reengajamento'}</small></div><div class="right flex">${button('Abrir contato','profile',t.contactId,'secondary small')}<button class="icon-button" data-action="task-done" data-id="${t.id}" aria-label="Concluir ação">${icon('check')}</button></div></div>`).join('')||empty('Nenhuma ação pendente. Os laços estão sendo bem cuidados.'))}
function download(name,data,type='text/csv;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows){return '\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(';')).join('\r\n')}
function exportContacts(){const cs=filterContacts().filter(c=>page==='donors'?c.plan:tab==='leads'?!c.plan:tab==='donors'?c.plan:true);download('relacionamentos-luz.csv',csv([['Nome','Email','Telefone','Tipo','Origem','Funil','Etapa','Status','Identificação'],...cs.map(c=>[c.name,c.email,c.phone,c.type,c.origin,c.funnel,D.STAGES[c.stage],c.plan?.status||'Potencial doador',D.enrolled(state,c)?'Sócio Inscrito':''])]));toast('Relacionamentos exportados.')}
function exportFinance(report=false){if(report){exportReportCSV();return}if(financeTab==='pending'){const ps=D.pending(state).filter(p=>(!filters.period||p.period===filters.period)&&(!filters.q||p.name.toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.status||p.overdue));download('pendencias-luz.csv',csv([['Doador','Competencia','Vencimento','Saldo','Situacao'],...ps.map(p=>[p.name,p.period,p.due,p.amount,p.overdue?'Em atraso':'A vencer'])]));return}const ps=state.payments.filter(p=>(!filters.period||p.date.startsWith(filters.period))&&(!filters.mode||p.mode===filters.mode)&&(!filters.stage||String(state.contacts.find(c=>c.id===p.contactId)?.stage)===filters.stage)&&(!filters.q||state.contacts.find(c=>c.id===p.contactId)?.name.toLowerCase().includes(filters.q.toLowerCase())));download('contribuicoes-luz.csv',csv([['Recibo','Doador','Valor R$','Pagamento','Competencia','Modalidade','Destinacao','Pix','Operador'],...ps.map(p=>[p.receipt,state.contacts.find(c=>c.id===p.contactId).name,p.amount,p.date,p.period,p.mode,p.destination,p.pix,p.actorName])]));toast('Contribuições exportadas.')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id||'';if(a==='theme'){toggleTheme();return}try{if(!['demo','recover','close','reset-link'].includes(a))activeUser();switch(a){case'demo':{const u=state.users.find(u=>u.id===id);$('[name=email]').value=u.email;$('[name=password]').value='Esperanca@2026';$('#auth-form').requestSubmit();break}case'nav':navigate(id);break;case'menu':$('.sidebar').classList.toggle('open');break;case'logout':D.audit(state,user,'Saída do sistema',null);save();logout();break;case'close':closeModal();break;case'profile':profile(id);break;case'contact':contactForm(id);break;case'move':moveForm(id);break;case'convert':convertForm(id);break;case'adherence':adherence(id);break;case'interaction':interactionForm(id);break;case'response':responseForm(id);break;case'donor-status':statusForm(id);break;case'payment':paymentForm(id);break;case'payment-pending':{const[c,p]=id.split('|');paymentForm(c,p);break}case'receipt':receipt(id);break;case'receipt-email':receiptEmailForm(id);break;case'report-pdf':reportPrint();break;case'intake-new':intakeForm();break;case'intake-edit':intakeForm(id);break;case'intake-review':intakeReview(id);break;case'intake-activate':D.activateIntake(state,user,id,true);save();closeModal();render();break;case'intake-pause':D.activateIntake(state,user,id,false);save();render();break;case'intake-retry':{const run=state.intakeRuns.find(r=>r.id===id);D.retryIntake(state,user,id);save();profile(run.contactId);break;}case'print':window.print();break;case'attachment':{const p=state.payments.find(p=>p.id===id);const link=document.createElement('a');link.href=p.attachment.data;link.download=p.attachment.name;link.click();break}case'loss-move':moveLossForm(id);break;case'automation-new':automationForm();break;case'automation-edit':automationForm(id);break;case'automation-review':automationReview(id);break;case'automation-pause':D.setAutomationActive(state,user,id,false);save();render();toast('Automação pausada. Envios pendentes cancelados.');break;case'automation-run':automationRunDetail(id);break;case'automation-now':D.processAutomations(state,new Date(),id);save();closeModal();render();automationRunDetail(id);break;case'automation-retry':D.retryAutomation(state,user,id);save();closeModal();render();automationRunDetail(id);break;case'automation-cancel':D.cancelAutomationRuns(state,r=>r.id===id,'Cancelamento solicitado por '+user.name);save();closeModal();render();automationRunDetail(id);break;case'cadence-exit':exitCadenceForm(id);break;case'cadence-resume':resumeCadenceForm(id);break;case'funnel-view':funnelView=id;render();break;
case'funnel-stage':funnelMobileStage=Number(id);render();break;
case'select-contact':if(emailEligible(state.contacts.find(c=>c.id===id))){if(b.checked)selectedContacts.add(id);else selectedContacts.delete(id)}render();$('[data-action=select-contact][data-id="'+id+'"]')?.focus({preventScroll:true});break;
case'select-filtered':{const eligible=visibleContacts().filter(emailEligible);eligible.forEach(c=>b.checked?selectedContacts.add(c.id):selectedContacts.delete(c.id));render();$('[data-action=select-filtered]')?.focus({preventScroll:true});break}
case'clear-selection':selectedContacts.clear();render();break;
case'bulk-email':bulkEmailForm();break;case'email-new':selectedContacts.clear();emailComposeForm();break;case'email-tab':emailTab=id;filters.q='';filters.status='';render();break;case'email-edit':{const m=state.mailings.find(m=>m.id===id);selectedContacts=new Set(m.contacts);emailComposeForm(m,id);break;}case'email-review':emailReview(id);break;case'email-pause':D.setMailingStatus(state,user,id,'paused');save();render();toast('Envios futuros pausados.');break;case'email-cancel':emailCancel(id);break;case'email-detail':emailMailingDetail(id);break;case'email-run':emailRunDetail(id);break;case'email-simulate':D.simulateMailing(state,user,id);save();render();emailMailingDetail(id);break;
case'email-pick':if(emailEligible(state.contacts.find(c=>c.id===id))){if(b.checked)selectedContacts.add(id);else selectedContacts.delete(id)}updateEmailRecipients();break;
case'email-select-all':recipientMatches().filter(emailEligible).forEach(c=>b.checked?selectedContacts.add(c.id):selectedContacts.delete(c.id));updateEmailRecipients();break;
case'email-clear':selectedContacts.clear();updateEmailRecipients();break;
case'contact-tab':tab=id;contactPage=1;render();break;case'finance-tab':financeTab=id;filters.mode='';filters.status='';render();break;case'clear':filters={q:'',origin:'',owner:'',period:'',funnel:'',status:'',mode:'',stage:''};render();break;case'prev':contactPage--;render();break;case'next':contactPage++;render();break;case'list':listForm(id);break;case'list-detail':listDetail(id);break;case'list-contacts':listContacts(id);break;case'import':importForm(id);break;case'csv-template':download('modelo-contatos-luz.csv',csv([['nome','email','telefone'],['Novo Contato','novo@exemplo.com','86999990000']]));break;case'campaign':campaignForm(id);break;case'contact-mail':campaignForm('',id);break;case'campaign-detail':{const c=state.campaigns.find(c=>c.id===id);modal(esc(c.subject),`<p class="muted" style="margin-bottom:18px">${time(c.at)} · ${c.contacts.length} destinatários</p><div class="campaign-preview">${esc(c.body)}</div><h3 style="margin:22px 0 10px">Destinatários</h3><p style="font-size:12px">${c.contacts.map(id=>esc(state.contacts.find(c=>c.id===id)?.name||'Contato removido')).join(', ')}</p>`);break}case'remove-list-contact':{const[l,c]=id.split('|'),list=state.lists.find(x=>x.id===l);list.contacts=list.contacts.filter(x=>x!==c);D.audit(state,user,'Contato removido da lista',c,list.name);save();render();listDetail(l);break}case'user':userForm(id);break;case'recover':recover();break;case'reset-link':closeModal();setTimeout(()=>{user=null;sessionStorage.removeItem(SESSION);render()},0);break;case'tasks':tasks();break;case'task-done':{const t=state.tasks.find(t=>t.id===id);t.done=true;D.audit(state,user,t.intakeRunId?'Acompanhamento concluído':'Reengajamento concluído',t.contactId,t.text);save();render();tasks();break}case'export-contacts':exportContacts();break;case'export-finance':exportFinance();break;case'export-report':exportFinance(true);break;case'delete-contact':{admin();const c=state.contacts.find(c=>c.id===id);if(state.payments.some(p=>p.contactId===id)){modal('Uma história que precisa ser preservada','<p>Este doador possui histórico financeiro e seu cadastro não pode ser excluído. Para encerrar a recorrência, altere o status para Cancelado.</p>',button('Voltar à ficha','profile',id));break}modal('Excluir este relacionamento?',`<p>O cadastro de <b>${esc(c.name)}</b> será removido. Esta ação requer confirmação.</p>`,button('Manter cadastro','profile',id)+button('Confirmar exclusão','confirm-delete',id,'danger'));break}case'confirm-delete':{admin();if(state.payments.some(p=>p.contactId===id))throw Error('Este contato possui histórico financeiro.');const c=state.contacts.find(c=>c.id===id);D.audit(state,user,'Contato excluído',null,c.name);state.contacts=state.contacts.filter(c=>c.id!==id);state.lists.forEach(l=>l.contacts=l.contacts.filter(x=>x!==id));state.tasks=state.tasks.filter(t=>t.contactId!==id);save();closeModal();render();toast('Cadastro excluído.');break}}}catch(err){toast(err.message,'error')}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
['pointerdown','keydown'].forEach(event=>document.addEventListener(event,()=>{if(user&&Date.now()-lastActivity<=30*60*1000){lastActivity=Date.now();sessionStorage.setItem(SESSION,JSON.stringify({id:user.id,last:lastActivity}))}}));
setInterval(()=>{if(user){if(Date.now()-lastActivity>30*60*1000)logout('Sua sessão foi encerrada por inatividade.');else if(!state.users.find(u=>u.id===user.id)?.active)logout('Seu acesso foi inativado.');else if(D.processAutomations(state)+D.processMailings(state)){save();if(page==='emails'&&!$('#modal').open)render()}}},15000);
window.addEventListener('hashchange',()=>{if(!user){closeModal();render()}});
window.addEventListener('storage',e=>{if(e.key===THEME_KEY){applyTheme(['light','dark'].includes(e.newValue)?e.newValue:(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));return}if(e.key===KEY&&e.newValue){try{state=D.repairLegacyHistory(JSON.parse(e.newValue));if(user){const u=state.users.find(u=>u.id===user.id);if(!u?.active){logout('Seu acesso foi inativado.');return}user=u;closeModal();render()}}catch{toast('Não foi possível sincronizar os dados deste navegador.','error')}}});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',e=>{try{if(!localStorage.getItem(THEME_KEY))applyTheme(e.matches?'dark':'light')}catch{}});
async function init(){try{const raw=localStorage.getItem(KEY);state=raw?D.repairLegacyHistory(JSON.parse(raw)):D.seed();if(state.version!==1||!Array.isArray(state.contacts))throw Error('Dados locais incompatíveis.');if(!state.users.length){state.users=[{id:'admin',name:'Marina Costa',email:'admin@luz.exemplo',role:'Administrador',active:true,...await credentials('Esperanca@2026')},{id:'operator',name:'João Oliveira',email:'operador@luz.exemplo',role:'Operador de Captação',active:true,...await credentials('Esperanca@2026')}];save()}const rawSession=sessionStorage.getItem(SESSION),session=rawSession?JSON.parse(rawSession):null;if(session&&Date.now()-session.last<30*60*1000&&!location.hash.includes('redefinir=')){user=state.users.find(u=>u.id===session.id&&u.active);lastActivity=session.last}D.reconcile(state,{id:'system',name:'Sistema'});save();render()}catch(err){$('#app').innerHTML=`<div class="login-content" style="min-height:100vh"><div class="login-form">${brand()}<h2 style="margin-top:35px">Vamos preparar nosso espaço.</h2><p>${esc(err.message)}</p><p>Execute <b>node server.js</b> e abra <b>http://localhost:3000</b>.</p><small>Para remover dados locais incompatíveis, limpe o armazenamento deste site no navegador.</small></div></div>`}}
init();
function recipientMatches(){
  const query=($f('#email-recipient-search')?.value||'').trim().toLocaleLowerCase('pt-BR');
  const link=$f('[name=recipientLink]')?.value,origin=$f('[name=recipientOrigin]')?.value,list=state.lists.find(l=>l.id===$f('[name=recipientList]')?.value);
  return state.contacts.filter(c=>(!query||[c.name,c.email].some(x=>String(x||'').toLocaleLowerCase('pt-BR').includes(query)))&&(!link||(link==='leads'?!c.plan:Boolean(c.plan)))&&(!origin||c.origin===origin)&&(!list||list.contacts.includes(c.id)));
}
function updateEmailRecipients(){
  const focusedId=document.activeElement?.dataset.action==='email-pick'?document.activeElement.dataset.id:null;
  cleanContactSelection();
  const matches=recipientMatches(),eligible=matches.filter(emailEligible),allSelected=eligible.length>0&&eligible.every(c=>selectedContacts.has(c.id));
  $f('#email-recipient-list').innerHTML=matches.map(c=>`<label class="recipient-option ${selectedContacts.has(c.id)?'is-picked':''} ${emailEligible(c)?'':'is-unavailable'}"><input type="checkbox" data-action="email-pick" data-id="${c.id}" ${selectedContacts.has(c.id)?'checked':''} ${emailEligible(c)?'':'disabled'} aria-label="Enviar e-mail para ${esc(c.name)}"><span class="recipient-text"><b>${esc(c.name)}</b><small>${esc(c.email||'Sem e-mail cadastrado')}</small>${!emailEligible(c)?`<span class="recipient-reason">${c.optOut?'Descadastrado de e-mails':'Sem e-mail válido'}</span>`:''}</span></label>`).join('')||empty('Nenhum contato encontrado.');
  const outside=[...selectedContacts].filter(id=>!matches.some(c=>c.id===id)).length;
  $f('#email-selected-count').textContent=selectedContacts.size+' '+(selectedContacts.size===1?'destinatário selecionado':'destinatários selecionados')+(outside?' · '+outside+' fora do filtro':'');
  const all=$f('#email-select-all');all.checked=allSelected;all.indeterminate=!allSelected&&eligible.some(c=>selectedContacts.has(c.id));all.disabled=!eligible.length;
  $f('#email-filter-count').textContent=eligible.length+' disponíveis';
  $f('[type=submit]').disabled=selectedContacts.size===0;
  if(focusedId)$f('[data-action=email-pick][data-id="'+focusedId+'"]')?.focus({preventScroll:true});
}
function bulkEmailForm(draft={subject:'',body:''}){emailComposeForm(draft)}

$('#modal').addEventListener('close',()=>{if(!$('#modal').open&&user&&['contacts','donors'].includes(page))render()});
